     * @param  string|null  $securityUpdates  Whether the system applies expedited security updates for the current major version.
     * @param  string|null  $stagingDir  The absolute directory path to the staging directory for updates.
     * @param  string|null  $updates  When the system will check for updates.
     * @param  array<string, mixed>  $extra  Further parameters, sent as given.
     *
     * @throws WhmException
     *
     * @see https://api.docs.cpanel.net/specifications/whm.openapi/updates/cpupdate-update_updateconf
     */
    public function updateUpdateconf(
        ?string $cpanel = null,
        ?string $rpmup = null,
        ?string $sarulesup = null,
        ?string $securityUpdates = null,
        ?string $stagingDir = null,
        ?string $updates = null,
        array $extra = [],
    ): WhmResponse {
        return $this->invoke('update_updateconf', [
            'CPANEL' => $cpanel,
